set-variable.value:
@{
        var jwt = context.Variables.GetValueOrDefault<Jwt>("finops-jwt");
        return jwt == null ? "" : (jwt.Claims.GetValueOrDefault("oid", new string[0]).FirstOrDefault() ?? "");
    }

@{
        var jwt = context.Variables.GetValueOrDefault<Jwt>("finops-jwt");
        return jwt == null ? "" : (jwt.Claims.GetValueOrDefault("tid", new string[0]).FirstOrDefault() ?? "");
    }

@{
        var jwt = context.Variables.GetValueOrDefault<Jwt>("finops-jwt");
        if (jwt == null) { return "unknown"; }
        return jwt.Claims.ContainsKey("scp") ? "user" : "agent";
    }

@{
        var jwt = context.Variables.GetValueOrDefault<Jwt>("finops-jwt");
        var fromToken = jwt == null ? "" : (jwt.Claims.GetValueOrDefault("azp", jwt.Claims.GetValueOrDefault("appid", new string[0])).FirstOrDefault() ?? "");
        return fromToken != "" ? fromToken : context.Request.Headers.GetValueOrDefault("x-finops-agent-id", "unknown");
    }

trace.message:
@{
          return new JObject(
              new JProperty("request_id", context.RequestId.ToString()),
              new JProperty("api", context.Api.Name),
              new JProperty("caller_oid", (string)context.Variables["finops-caller-oid"]),
              new JProperty("caller_tid", (string)context.Variables["finops-caller-tid"]),
              new JProperty("caller_type", (string)context.Variables["finops-caller-type"]),
              new JProperty("agent_id", (string)context.Variables["finops-agent-id"])
          ).ToString(Newtonsoft.Json.Formatting.None);
      }
